/** Where a hosted environment keeps a value. */
export type VariableStore = 'convex' | 'worker' | 'github';

export type DeploymentVariable = {
  /** `you` set it once; `release` sets it on every deploy. */
  setBy: 'you' | 'release';
  /** Optional values may be absent; when set, everything in `requires` must be set too. */
  optional?: true;
  requires?: readonly string[];
  /** What the value is for. */
  description: string;
  /** How to get or set it. */
  how: string;
};

/**
 * Every variable a hosted environment (beta, production) needs, by where it lives: the Convex
 * deployment, the web app's Void Worker, and the GitHub environment that releases it. The
 * backend's typed env, the Worker's env schema, the setup checklist, and the release preflight
 * all read this one definition.
 */
export const deploymentVariables = {
  convex: {
    SITE_URL: {
      setBy: 'release',
      description: 'The web app origin; authentication and passkeys use it.',
      how: 'Set by every release from the environment settings.'
    },
    BETTER_AUTH_SECRET: {
      setBy: 'release',
      description: 'Signs Better Auth sessions.',
      how: 'Generated by the first release and never replaced.'
    },
    AUTH_EMAIL_RELAY_SECRET: {
      setBy: 'you',
      description: 'Lets Convex hand verification and reset mail to the web Worker.',
      how: 'A long random value (`openssl rand -base64 32`), set with `convex env set`; the web Worker needs the same value.'
    },
    STRIPE_SECRET_KEY: {
      setBy: 'you',
      optional: true,
      requires: ['STRIPE_WEBHOOK_SECRET'],
      description: 'Turns on payments.',
      how: 'Only for payments: the Stripe secret key, set with `convex env set`.'
    },
    STRIPE_WEBHOOK_SECRET: {
      setBy: 'you',
      optional: true,
      description: "Verifies Stripe's webhook calls.",
      how: 'Only for payments: the webhook signing secret, set with `convex env set`.'
    }
  },
  worker: {
    AUTH_EMAIL_RELAY_SECRET: {
      setBy: 'you',
      description: 'Accepts authentication mail only from Convex.',
      how: 'The same value as in Convex: `void secret put AUTH_EMAIL_RELAY_SECRET` in apps/web.'
    }
  },
  github: {
    CONVEX_DEPLOY_KEY: {
      setBy: 'you',
      description: "Deploys the environment's Convex backend.",
      how: 'Convex dashboard → production deployment → Settings → generate a production deploy key; store it as a secret of the GitHub environment.'
    },
    CLOUDFLARE_API_TOKEN: {
      setBy: 'you',
      description: 'Lets Void deploy the Workers, their domains, and email.',
      how: 'Cloudflare → My Profile → API Tokens, with the permissions the setup checklist lists; store it as a secret of the GitHub environment.'
    }
  }
} as const satisfies Record<VariableStore, Record<string, DeploymentVariable>>;

export type VariableName<S extends VariableStore> = keyof (typeof deploymentVariables)[S] & string;

export function variableNames<S extends VariableStore>(store: S): VariableName<S>[] {
  return Object.keys(deploymentVariables[store]) as VariableName<S>[];
}

/** One schema entry per variable in `store`, keeping the names in the resulting type. */
export function schemaFor<S extends VariableStore, T>(
  store: S,
  entry: () => T
): Record<VariableName<S>, T> {
  return Object.fromEntries(variableNames(store).map((name) => [name, entry()])) as Record<
    VariableName<S>,
    T
  >;
}

/**
 * The variables in `store` that still need to be set, given the names already present: every
 * value you set yourself that isn't optional, plus whatever a present optional value requires.
 * Values the release sets are left to the release.
 */
export function missingVariables(store: VariableStore, present: ReadonlySet<string>): string[] {
  const entries = Object.entries(deploymentVariables[store]) as [string, DeploymentVariable][];
  const missing = new Set<string>();
  for (const [name, variable] of entries) {
    if (variable.setBy === 'you' && !variable.optional && !present.has(name)) missing.add(name);
    if (present.has(name))
      for (const required of variable.requires ?? [])
        if (!present.has(required)) missing.add(required);
  }
  return [...missing];
}
